   assert.notExists(U.$('library').querySelector('.compact-select-all'),'紧凑工具栏不显示独立全选按钮');assert.notExists(U.$('library').querySelector('.topic-types'),'素材类型不再占一个独立折叠区');
   const type=typeControl(),selectedType=U.p.materialCatalog.entries[source.id].type;assert.exists(type);assert.equal(selectedType,'实验设置','既有实验材料沿用原生分类');assert.notEqual(U.p.materialCatalog.entries[unmatched.id].type,selectedType);assert.isTrue([...type.options].some(option=>option.value===selectedType),'筛选器提供已有材料的原生类型');
   U.$('library').querySelector('.search-filter-toggle').click();assert.isFalse(type.closest('.search-filter-popover').hidden);assert.isAbove(type.getBoundingClientRect().height,15,'类型选择器在实际筛选菜单中可用');
   type.value=selectedType;type.dispatchEvent(new (fw().Event)('change',{bubbles:true}));await wait(()=>rows().some(row=>row.dataset.material===source.id)&&!rows().some(row=>row.dataset.material===unmatched.id),'类型筛选真实材料');
   const verification=U.$('library').querySelector('.search-filter-popover select[aria-label="核验状态"]');verification.value='unverified';verification.dispatchEvent(new (fw().Event)('change',{bubbles:true}));
   const matchedIDs=rows().map(row=>row.dataset.material);assert.isAbove(matchedIDs.length,0);for(const id of matchedIDs)assert.equal(U.p.materialCatalog.entries[id].type,selectedType,'筛选结果排除不匹配类型');assert.notInclude(matchedIDs,unmatched.id);
   const firstRow=rows()[0];firstRow.focus();const selectAll=new (fw().KeyboardEvent)('keydown',{key:'a',ctrlKey:true,bubbles:true,cancelable:true});firstRow.dispatchEvent(selectAll);assert.isTrue(selectAll.defaultPrevented,'结果列表保留 Ctrl+A 全选');assert.sameMembers(U.p.ui.catalog.selection,matchedIDs);assert.sameMembers(rows().filter(row=>row.getAttribute('aria-selected')==='true').map(row=>row.dataset.material),matchedIDs);assert.notInclude(U.p.ui.catalog.selection,unmatched.id,'全选不包含被筛掉的材料');
   await U.persist();await wait(()=>U.A.get(projectID).ui.catalog.type===selectedType&&U.A.get(projectID).ui.catalog.selection.length===matchedIDs.length,'保存实际筛选与选择');assert.sameMembers(U.A.get(projectID).ui.catalog.selection,matchedIDs,'实际保存的选择仍是筛选结果');
   U.renderLibrary();assert.equal(typeControl().value,selectedType,'同一 DOM 重绘保留类型值');assert.sameMembers(rows().map(row=>row.dataset.material),matchedIDs);assert.sameMembers(U.p.ui.catalog.selection,matchedIDs);
   tab('structure');tab('materials');assert.equal(typeControl().value,selectedType,'切换面板后重建筛选器仍显示当前类型');assert.equal(U.$('library').querySelector('select[aria-label="核验状态"]').value,'unverified');assert.sameMembers(rows().map(row=>row.dataset.material),matchedIDs);assert.sameMembers(rows().filter(row=>row.getAttribute('aria-selected')==='true').map(row=>row.dataset.material),matchedIDs);
   const reset=[...U.$('material-results').querySelectorAll('.active-filters button')].find(button=>button.textContent==='清除筛选');assert.exists(reset);reset.click();await wait(()=>typeControl()?.value===''&&U.p.ui.catalog.type===''&&Object.keys(U.p.ui.catalog.facets).length===0,'清除筛选同步实际选择器');assert.equal(U.$('library').querySelector('select[aria-label="核验状态"]').value,'');assert.equal(U.$('material-search').value,'');assert.isEmpty(U.materialQuery);assert.isEmpty(U.p.ui.catalog.selection);assert.include(rows().map(row=>row.dataset.material),source.id);assert.include(rows().map(row=>row.dataset.material),unmatched.id);U.renderLibrary();assert.equal(typeControl().value,'','清空状态重绘后不回显旧类型');
   assert.deepEqual(U.p.materials.map(m=>m.id),materialIDs,'筛选与键盘全选不删除材料');assert.equal(baseline(),before,'筛选不改写正文或材料引用');report.materialFilter={type:selectedType,matchedIDs,excludedID:unmatched.id,ctrlA:true,resetType:typeControl().value};
