 it('places a detached Logo inside the article bounds and moves it with a side-panel conversation',async()=>{U.p.ui.leftOpen=true;U.p.ui.rightOpen=true;U.applyPanels();const main=U.$('workspace').querySelector('main').getBoundingClientRect(),surface=U.conversationSurface;surface.root.dispatchEvent(new (fw().CustomEvent)('easysch-conversation-statechange',{bubbles:true,detail:{orbPosition:{x:main.left+20,y:main.top+100}}}));const rect=U.aiOrb.button.getBoundingClientRect();assert.isAtLeast(rect.left,main.left-12);assert.isAtMost(rect.right,main.right+12);surface.dock('right');assert.isTrue(U.aiOrb.button.hidden);surface.undock({nearLogo:false});assert.isFalse(U.aiOrb.button.hidden);surface.hide();});
